useLastCallback(() => {
    if (emptySelectionMessage && !selectedCountryIds.length) {
      showNotification({ message: emptySelectionMessage });
      return;
    }

    onSubmit(selectedCountryIds);
    onClose();
  })

useLastCallback((event: KeyboardEvent) => {
    const target = event.target instanceof HTMLElement ? event.target : undefined;
    const dialog = document.getElementById(searchInputId)?.closest('dialog');
    if (!target || !dialog?.contains(target)) return false;
    if (target.closest('button, a[href], input[type=checkbox], input[type=radio], select, '
      + '[role=button], [role=checkbox], [role=radio], [role=option], .MenuItem')) {
      return ALLOW_KEYBOARD_EVENT_PROPAGATION;
    }
    event.preventDefault();
    if (!event.repeat) handleSubmit();
    return true;
  })

useLastCallback(() => {
    if (isLoading || !password.length) return;
    checkPassword({
      currentPassword: password,
      onSuccess: () => {
        onSubmit(password);
        setPassword('');
        setShouldShowPassword(false);
      },
    });
  })

useCallback(() => {
    if (renderingStickerSet) {
      toggleStickerSet({ stickerSetId: renderingStickerSet.id });
      onClose();
    }
  }, [onClose, renderingStickerSet, toggleStickerSet])

useLastCallback((password: string) => {
    if (!renderingModal) return;
    processMonetizationRevenueWithdrawalUrl({
      peerId: renderingModal.chatId,
      currentPassword: password,
    });
  })

useCallback(() => {
    const idsToRemove = initialSelectedFolderIds.filter((id) => !selectedFolderIds.includes(id)).map(Number);
    const idsToAdd = selectedFolderIds.filter((id) => !initialSelectedFolderIds.includes(id)).map(Number);

    editChatFolders({ chatId, idsToRemove, idsToAdd });
    onClose();
  }, [chatId, editChatFolders, initialSelectedFolderIds, onClose, selectedFolderIds])

useCallback(() => {
    let mutedUntil: number;
    if (muteUntilOption === MuteDuration.Forever) {
      mutedUntil = MUTE_INDEFINITE_TIMESTAMP;
    } else {
      mutedUntil = Math.floor(Date.now() / 1000) + Number(muteUntilOption);
    }
    if (topicId) {
      updateTopicMutedState({ chatId, topicId, mutedUntil });
    } else {
      updateChatMutedState({ chatId, mutedUntil });
    }
    onClose();
  }, [chatId, muteUntilOption, onClose, topicId])

useCallback(() => {
    const noteToSend = note.trim() ? { text: note, entities: [] } : undefined;

    if (isByPhoneNumber || !userId) {
      importContact({
        firstName,
        lastName,
        phoneNumber: phone,
      });
    } else {
      updateContact({
        userId,
        firstName,
        lastName,
        shouldSharePhoneNumber,
        note: noteToSend,
      });
    }
  }, [firstName, importContact, isByPhoneNumber, lastName, note, phone, shouldSharePhoneNumber, updateContact, userId])

useLastCallback(() => {
    if (!canSubmit) return;

    if (isEditMode) {
      const tone = getInputTone(toneToEdit);
      updateAiTone({
        tone,
        title: title.trim(),
        emojiId: emojiId!,
        prompt: prompt.trim(),
        shouldDisplayAuthor: shouldDisplayAuthor || undefined,
      });
    } else {
      createAiTone({
        title: title.trim(),
        emojiId: emojiId!,
        prompt: prompt.trim(),
        shouldDisplayAuthor: shouldDisplayAuthor || undefined,
      });
    }
    handleClose();
  })

useLastCallback((e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!canSubmit) {
      return;
    }

    onSubmit(text, url);
  })

useCallback(() => {
    confirmAttachBotInstall({
      isWriteAllowed: Boolean(bot?.shouldRequestWriteAccess),
    });
  }, [confirmAttachBotInstall, bot])

useLastCallback(() => {
    if (!day || !month) return;
    const birthday = {
      day,
      month,
      year,
    };

    if (suggestForUserId) {
      suggestBirthday({ userId: suggestForUserId, birthday });
    } else {
      updateBirthday({ birthday });
    }
    closeBirthdaySetupModal();
  })

useLastCallback(() => {
    if (!boost) {
      if (!isCurrentUserPremium) {
        openPremiumDialog();
        return;
      }

      closeBoostModal();
      return;
    }

    if (!canBoostMore) {
      closeBoostModal();
      return;
    }

    if (boost.cooldownUntil) {
      openWaitDialog();
      return;
    }

    if (isReplacingBoost) {
      openReplaceModal();
      return;
    }

    handleApplyBoost();
  })

useLastCallback(() => {
    if (!renderingAuctionState?.gift.id || !modal) return;
    const { peerId, message, shouldHideName } = modal;
    const isUpdateBid = Boolean(userState?.bidAmount);

    sendStarGiftAuctionBid({
      giftId: renderingAuctionState.gift.id,
      bidAmount: selectedBidAmount,
      peerId,
      message: message ? { text: message } : undefined,
      shouldHideName,
      isUpdateBid,
    });
  })

useLastCallback(() => {
    if (!renderingModal?.auctionGiftId) return;

    closeGiftAuctionChangeRecipientModal();
    openGiftAuctionBidModal({
      auctionGiftId: renderingModal.auctionGiftId,
      peerId: renderingModal.newPeerId,
      message: renderingModal.message,
      shouldHideName: renderingModal.shouldHideName,
    });
  })

useLastCallback(() => {
    const peer = recipientPeer || currentUser;
    const price = getResalePrice(shouldPayInTon);
    if (!peer || !price || gift?.type !== 'starGiftUnique') return;
    closeConfirmModal();
    closeGiftModal();
    buyStarGift({ peerId: peer.id, slug: gift.slug, price });
  })

useLastCallback(() => {
    if (!renderingModal?.gift.inputGift || !renderingModal.price) return;

    removeGiftDescription({
      gift: renderingModal.gift.inputGift,
      price: renderingModal.price,
    });
  })

useLastCallback(() => {
    if (!renderingModal) return;

    acceptStarGiftOffer({ messageId: renderingModal.messageId });
    closeGiftOfferAcceptModal();
  })

useLastCallback(() => {
    if (!renderingModal?.gift.inputGift || !renderingModal.recipientId) return;

    transferGift({
      gift: renderingModal.gift.inputGift,
      recipientId: renderingModal.recipientId,
      transferStars: renderingModal.gift.transferStars,
    });

    closeGiftTransferConfirmModal();
    openChat({ id: renderingModal.recipientId });

    closeGiftModal();
    closeGiftTransferModal();
  })

useLastCallback((password: string) => {
    processStarGiftWithdrawal({
      gift: renderingModal!.gift.inputGift!,
      password,
    });
  })

useLastCallback(() => {
    if (canUse) {
      applyGiftCode({ slug: modal!.slug });
      return;
    }
    closeGiftCodeModal();
  })

useCallback(() => {
    if (!modal?.directInfo) {
      actions.closePriceConfirmModal();
      return;
    }

    const { currency, newAmount } = modal;
    const isTon = currency === 'TON';
    const currentBalance = isTon ? tonBalance : starBalance?.amount;

    if (currentBalance === undefined) {
      actions.closePriceConfirmModal();
      return;
    }

    if (currentBalance < newAmount!) {
      actions.openStarsBalanceModal({
        currency: isTon ? 'TON' : 'XTR',
        tabId: getCurrentTabId(),
      });
      actions.closePriceConfirmModal();
      return;
    }

    actions.sendStarPaymentForm({
      directInfo: modal.directInfo,
      tabId: getCurrentTabId(),
    });
    actions.closePriceConfirmModal();
  }, [modal, starBalance, tonBalance, actions])

useLastCallback(() => {
    onSubmit(text);
  })

useLastCallback(() => {
    if (isSubmitDisabled) return;

    if (!chatId || !userId) return;

    editChatParticipantRank({
      chatId,
      userId,
      rank,
    });

    handleClose();
  })

useLastCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key !== 'Enter') return;

    e.preventDefault();
    handleSubmit();
  })

useLastCallback(() => {
    const balance = starsBalanceState?.balance;
    if (amount === undefined || balance === undefined) {
      return;
    }

    if (amount > balance.amount) {
      openStarsBalanceModal({
        originStarsPayment: modal,
      });
      return;
    }

    sendStarPaymentForm({});
    markLoading();
  })

useLastCallback(() => {
    closeChatRefundModal();
    if (!userId) return;

    toggleNoPaidMessagesException ({ userId, shouldRefundCharged: shouldRefundStars });
  })

useLastCallback(() => {
    if (!subscription) {
      return;
    }

    switch (buttonState) {
      case 'refulfill': {
        fulfillStarsSubscription({ id: subscription.id });
        break;
      }
      case 'restart': {
        if (subscription.chatInviteHash) {
          checkChatInvite({ hash: subscription.chatInviteHash });
        } else if (subscription.invoiceSlug) {
          openInvoice({
            type: 'slug',
            slug: subscription.invoiceSlug,
          });
        }
        loadStarStatus();
        break;
      }
      case 'renew': {
        changeStarsSubscription({ id: subscription.id, isCancelled: false });
        break;
      }
      case 'cancel': {
        changeStarsSubscription({ id: subscription.id, isCancelled: true });
        break;
      }
    }
    closeStarsSubscriptionModal();
  })

useLastCallback(() => {
    if (!renderingRequest) {
      return;
    }

    if (renderingRequest.matchCodes?.length && !effectiveMatchCode) {
      setDialogState('match-confirm');
      return;
    }

    if (renderingRequest.shouldRequestPhoneNumber) {
      setDialogState('phone');
      return;
    }

    submitAuth();
  })

useCallback((eventData: PaymentFormSubmitEvent['eventData']) => {
    const { credentials } = eventData;
    setSmartGlocalCardInfo(credentials);
    sendForm();
  }, [sendForm])

useLastCallback(() => {
    switch (step) {
      case PaymentStep.ShippingInfo:
        setIsLoading(true);
        validateRequest();
        break;

      case PaymentStep.Shipping:
        setStep(PaymentStep.Checkout);
        break;

      case PaymentStep.SavedPayments:
        setStep(PaymentStep.ConfirmPassword);
        break;

      case PaymentStep.ConfirmPassword:
        if (twoFaPassword === '') {
          return;
        }

        setIsLoading(true);
        validatePaymentPassword({ password: twoFaPassword });
        break;

      case PaymentStep.PaymentInfo:
        setIsLoading(true);
        sendCredentials();
        paymentDispatch({ type: 'changeSavedCredentialId', payload: '' });
        break;

      case PaymentStep.Checkout: {
        if (isPaymentFormUrl) {
          setIsLoading(true);
          setStep(PaymentStep.ConfirmPayment);
          return;
        }

        if (form?.savedInfo && !requestId && !paymentState.shipping) {
          setIsLoading(true);
          validateRequest();
          return;
        }

        if (
          paymentState.savedCredentialId
          && (!passwordValidUntil || passwordValidUntil <= (Date.now() / 1000 - NETWORK_REQUEST_TIMEOUT_S))
        ) {
          setStep(PaymentStep.ConfirmPassword);
          return;
        }

        if (
          !paymentState.savedCredentialId
          && (
            (nativeProvider === DEFAULT_PROVIDER && !stripeId)
            || (nativeProvider === DONATE_PROVIDER && !smartGlocalToken)
          )
        ) {
          setStep(PaymentStep.PaymentInfo);
          return;
        }

        const { phone, email, fullName } = paymentState;
        const shouldFillRequestedData = (invoice?.isEmailRequested && !email)
          || (invoice?.isPhoneRequested && !phone)
          || (invoice?.isNameRequested && !fullName);

        if ((invoice?.isShippingAddressRequested && !requestId) || shouldFillRequestedData) {
          setStep(PaymentStep.ShippingInfo);
          return;
        }

        if (invoice?.isShippingAddressRequested && !paymentState.shipping && shippingOptions?.length) {
          setStep(PaymentStep.Shipping);
          return;
        }

        setIsLoading(true);
        sendForm();
        break;
      }
    }
  })

